trojan_horse.source:
export const envelope = [23, 18, 39];

export default function build(api) {
  const planks = api.theme.wood.planks;
  const logs = api.theme.wood.log;
  const trapdoor = api.theme.wood.trapdoor;
  const plinth = api.theme.ground.plinth;

  function put(x, y, z, block) {
    if (
      x < 0 || y < 0 || z < 0 ||
      x >= api.size[0] || y >= api.size[1] || z >= api.size[2]
    ) {
      return;
    }
    api.set(x, y, z, block);
  }

  function box(x0, y0, z0, x1, y1, z1, block) {
    for (let x = x0; x <= x1; x++) {
      for (let y = y0; y <= y1; y++) {
        for (let z = z0; z <= z1; z++) {
          put(x, y, z, block);
        }
      }
    }
  }

  function profile(z) {
    if (z === 9 || z === 29) {
      return [8, 14, 5, 10];
    }
    if (z === 10 || z === 28) {
      return [6, 16, 4, 11];
    }
    if (z === 11 || z === 27) {
      return [5, 17, 3, 12];
    }
    return [4, 18, 3, 12];
  }

  function groundTop(x, z) {
    let top = Math.floor(api.heightAt(x, z));
    if (top < 0) {
      top = 0;
    }
    if (top > 2) {
      top = 2;
    }
    return top;
  }

  // A shaped clay-stone plinth follows the local terrain.
  for (let z = 9; z <= 29; z++) {
    const p = profile(z);
    for (let x = p[0]; x <= p[1]; x++) {
      const top = groundTop(x, z);
      for (let y = 0; y <= top; y++) {
        put(x, y, z, plinth);
      }
    }
  }

  // A short, solid stepped approach leads to the concealed side hatch.
  for (let x = 0; x <= 3; x++) {
    for (let z = 21; z <= 22; z++) {
      const top = Math.max(x, groundTop(x, z));
      for (let y = 0; y <= top; y++) {
        put(x, y, z, x === 3 ? logs : planks);
      }
    }
  }

  // Rounded timber barrel, left hollow through its middle.
  for (let z = 9; z <= 29; z++) {
    const p = profile(z);
    const xmin = p[0];
    const xmax = p[1];
    const ymin = p[2];
    const ymax = p[3];

    for (let x = xmin; x <= xmax; x++) {
      for (let y = ymin; y <= ymax; y++) {
        const inRoom =
          x >= 7 && x <= 15 &&
          y >= 4 && y <= 9 &&
          z >= 13 && z <= 25;

        const hatchGap =
          x >= 4 && x <= 6 &&
          y >= 4 && y <= 6 &&
          z >= 20 && z <= 22;

        if (inRoom || hatchGap) {
          continue;
        }

        const structural =
          x === xmin || x === xmax ||
          y === ymin || y === ymax ||
          z === 9 || z === 29;

        put(x, y, z, structural ? logs : planks);
      }
    }
  }

  // Four stout legs, each resting on a terrain-aware foundation.
  const legs = [
    [4, 6, 13, 15],
    [16, 18, 13, 15],
    [4, 6, 24, 26],
    [16, 18, 24, 26]
  ];

  for (let i = 0; i < legs.length; i++) {
    const leg = legs[i];
    for (let x = leg[0]; x <= leg[1]; x++) {
      for (let z = leg[2]; z <= leg[3]; z++) {
        const first = Math.max(1, groundTop(x, z) + 1);
        for (let y = first; y <= 5; y++) {
          put(x, y, z, y === first ? planks : logs);
        }
      }
    }
  }

  // Timber framing around the concealed hatch.
  for (let y = 4; y <= 7; y++) {
    put(4, y, 19, logs);
    put(4, y, 23, logs);
  }
  for (let z = 20; z <= 22; z++) {
    put(4, 7, z, logs);
  }

  // A connected outer frame supports the hinged hatch cover.
  for (let z = 20; z <= 23; z++) {
    for (let y = 3; y <= 5; y++) {
      put(2, y, z, logs);
    }
  }
  put(3, 4, 21, trapdoor);
  put(3, 4, 22, trapdoor);

  // Sloping neck rising from the front of the barrel.
  box(7, 9, 8, 15, 14, 12, planks);
  box(7, 10, 6, 15, 15, 8, planks);
  box(7, 11, 5, 15, 15, 6, planks);
  box(6, 12, 4, 16, 16, 5, planks);

  for (let z = 8; z <= 12; z++) {
    put(7, 9, z, logs);
    put(15, 9, z, logs);
  }
  for (let z = 5; z <= 8; z++) {
    put(7, 12, z, logs);
    put(15, 12, z, logs);
  }

  // A stepped mane runs up the rear edge of the neck.
  for (let i = 0; i < 5; i++) {
    const z = 12 - i;
    const y = 10 + i;
    put(6, y, z, logs);
    put(6, y + 1, z, logs);
  }

  // Head, cheeks, muzzle, and nose facing toward z = 0.
  box(7, 12, 8, 15, 15, 8, planks);
  box(6, 12, 5, 16, 16, 7, planks);
  box(7, 11, 3, 15, 15, 4, planks);
  box(7, 11, 2, 15, 14, 2, planks);
  box(8, 10, 0, 14, 13, 1, planks);

  for (let y = 12; y <= 15; y++) {
    put(6, y, 5, logs);
    put(16, y, 5, logs);
  }

  // Ears and small timber details give the head its horse-like expression.
  box(7, 16, 5, 9, 17, 6, logs);
  box(13, 16, 5, 15, 17, 6, logs);
  put(6, 14, 6, logs);
  put(16, 14, 6, logs);
  put(8, 11, 0, logs);
  put(14, 11, 0, logs);

  // A long, descending tail joined into the rear bulkhead.
  box(9, 8, 29, 13, 10, 31, logs);
  box(9, 7, 31, 13, 9, 33, planks);
  box(8, 6, 33, 12, 8, 35, logs);
  box(7, 5, 35, 11, 7, 37, planks);
  box(7, 4, 37, 10, 6, 38, logs);

  return {
    name: "Trojan Horse of Troy",
    seatY: 0,
    anchors: {
      door: [3, 4, 22]
    },
    interiors: [
      {
        min: [7, 4, 13],
        max: [15, 9, 25],
        kind: "quarters"
      }
    ]
  };
}

beached_warships.source:
export const envelope = [56, 18, 22];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];

  const seatY = 5;
  const wood = api.theme.wood;
  const ground = api.theme.ground;
  const stone = api.theme.stone;

  function inXZ(x, z) {
    return x >= 0 && x < W && z >= 0 && z < D;
  }

  function put(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  function terrainY(x, z) {
    let y = Math.floor(seatY + api.heightAt(x, z));

    if (y < 0) {
      return 0;
    }

    if (y >= H) {
      return H - 1;
    }

    return y;
  }

  function nominalBase(t) {
    return seatY + Math.floor((3 * t) / 22);
  }

  function shipX(ship, t) {
    return ship.x0 + ship.dir * t;
  }

  function radius(t) {
    if (t === 0 || t === 22) {
      return 0;
    }

    if (t === 1 || t === 21) {
      return 1;
    }

    if (t === 2 || t === 20) {
      return 2;
    }

    return 3;
  }

  function baseAt(t, x, z) {
    let b = nominalBase(t);
    const gy = terrainY(x, z);

    if (gy > b) {
      b = gy;
    }

    const cap = H - 7;

    if (b > cap) {
      b = cap;
    }

    if (b < 0) {
      b = 0;
    }

    return b;
  }

  function footing(x, z, top) {
    const gy = terrainY(x, z);

    for (let y = gy; y < top; y++) {
      put(x, y, z, ground.plinth);
    }
  }

  function lowColumn(x, z, block) {
    if (!inXZ(x, z)) {
      return;
    }

    const gy = terrainY(x, z);
    const lo = Math.min(gy, seatY);
    const hi = Math.max(gy, seatY);

    for (let y = lo; y < hi; y++) {
      put(x, y, z, ground.plinth);
    }

    put(x, hi, z, block);
  }

  function rubbleJoin(x, z, joinY, topBlock) {
    if (!inXZ(x, z)) {
      return;
    }

    const gy = terrainY(x, z);
    const lo = Math.min(gy, joinY);
    const hi = Math.max(gy, joinY);

    for (let y = lo; y < hi; y++) {
      put(x, y, z, ground.revetment);
    }

    put(x, joinY, z, topBlock);
  }

  const west = {
    x0: 3,
    dir: 1,
    cz: 6,
    id: 0
  };

  const east = {
    x0: 52,
    dir: -1,
    cz: 15,
    id: 1
  };

  function buildShip(ship) {
    for (let t = 0; t <= 22; t++) {
      const x = shipX(ship, t);
      const r = radius(t);
      const centerBase = baseAt(t, x, ship.cz);

      for (let y = seatY; y <= centerBase; y++) {
        put(x, y, ship.cz, wood.log);
      }

      for (let dz = -r; dz <= r; dz++) {
        const z = ship.cz + dz;
        const b = baseAt(t, x, z);

        footing(x, z, b);

        for (let q = 0; q < 4; q++) {
          const rr = q === 3 ? Math.max(0, r - 1) : r;

          if (Math.abs(dz) > rr) {
            continue;
          }

          const damage =
            (t * 13 + (dz + 3) * 7 + q * 5 + ship.id * 17) % 37;

          if (q === 3 && damage === 0) {
            continue;
          }

          let block = wood.planks;

          if (q === 0) {
            block = wood.log;
          } else if (
            q === 1 &&
            Math.abs(t * 2 + dz + ship.id) % 9 === 0
          ) {
            block = wood.log;
          } else if (
            q === 2 &&
            Math.abs(t * 3 + dz + ship.id * 2) % 6 === 0
          ) {
            block = wood.stripped;
          } else if (
            q === 3 &&
            Math.abs(t + dz + ship.id) % 7 === 0
          ) {
            block = wood.stripped;
          }

          if (
            q === 0 &&
            dz === 0 &&
            (t + ship.id) % 6 === 2
          ) {
            block = stone.accent;
          }

          put(x, b + q, z, block);
        }
      }

      if (r > 0) {
        const leftZ = ship.cz - r;
        const rightZ = ship.cz + r;
        const leftBase = baseAt(t, x, leftZ);
        const rightBase = baseAt(t, x, rightZ);

        put(x, leftBase + 3, leftZ, wood.log);
        put(x, rightBase + 3, rightZ, wood.log);

        if ((t + ship.id) % 6 !== 2) {
          put(x, leftBase + 4, leftZ, wood.log);
          put(x, rightBase + 4, rightZ, wood.log);
        }
      }

      if (r >= 2 && t % 4 === 0) {
        for (let dz = -r; dz <= r; dz++) {
          const z = ship.cz + dz;
          const ribBase = baseAt(t, x, z);
          put(x, ribBase + 2, z, wood.log);
        }
      }

      if (r >= 2 && (t + ship.id) % 4 === 1) {
        for (const side of [-1, 1]) {
          const z = ship.cz + side * r;
          const strakeBase = baseAt(t, x, z);
          put(x, strakeBase + 1, z, wood.stripped);
        }
      }
    }
  }

  buildShip(west);
  buildShip(east);

  function addProw(ship) {
    const t = 22;
    const x = shipX(ship, t);
    const z = ship.cz;
    const b = baseAt(t, x, z);

    put(x, b + 3, z, wood.planks);

    for (let k = 1; k <= 3; k++) {
      put(x, b + 3 + k, z, wood.log);
    }

    put(x + ship.dir, b + 5, z, wood.log);
    put(
      x + ship.dir,
      b + 5,
      z + (ship.id === 0 ? 1 : -1),
      wood.log
    );
    put(x + 2 * ship.dir, b + 5, z, wood.stripped);
  }

  function addMast(ship, t, tall) {
    const x = shipX(ship, t);
    const z = ship.cz;
    const b = baseAt(t, x, z);
    const deck = b + 3;

    put(x, deck, z, wood.planks);

    if (tall) {
      for (let k = 1; k <= 5; k++) {
        put(x, deck + k, z, wood.log);
      }

      for (let s = -3; s <= 3; s++) {
        const sparBlock = Math.abs(s) === 3 ? wood.stripped : wood.log;
        put(x, deck + 3, z + s, sparBlock);
      }

      for (let s = -2; s <= 0; s++) {
        put(x, deck + 4, z + s, wood.stripped);
      }

      const brokenX = x + ship.dir;
      put(brokenX, deck + 5, z, wood.log);
      put(brokenX, deck + 6, z, wood.log);
      put(brokenX, deck + 7, z, wood.stripped);
      put(x + 2 * ship.dir, deck + 7, z, wood.log);
    } else {
      for (let k = 1; k <= 3; k++) {
        put(x, deck + k, z, wood.log);
      }

      put(x + ship.dir, deck + 3, z, wood.log);
      put(x + ship.dir, deck + 4, z, wood.stripped);
    }
  }

  addProw(west);
  addProw(east);

  addMast(west, 8, true);
  addMast(west, 16, false);
  addMast(east, 12, true);
  addMast(east, 6, false);

  function addOar(ship, t, side, length, dx) {
    const x0 = shipX(ship, t);
    const z0 = ship.cz + side * radius(t);
    const startBase = baseAt(t, x0, z0);

    let tx = x0 + dx;
    let tz = z0 + side * length;

    if (tx < 0) {
      tx = 0;
    }

    if (tx >= W) {
      tx = W - 1;
    }

    if (tz < 0) {
      tz = 0;
    }

    if (tz >= D) {
      tz = D - 1;
    }

    const y0 = Math.min(H - 2, startBase + 3);
    const gy = terrainY(tx, tz);
    const ty = Math.max(1, Math.min(H - 2, gy + 1));

    let x = x0;
    let y = y0;
    let z = z0;

    put(x, y, z, wood.log);

    let steps = 0;

    while ((x !== tx || y !== ty || z !== tz) && steps < 100) {
      steps++;
      let moved = false;

      if (y !== ty && steps % 3 === 0) {
        y += y < ty ? 1 : -1;
        moved = true;
      } else if (z !== tz) {
        z += z < tz ? 1 : -1;
        moved = true;
      } else if (x !== tx) {
        x += x < tx ? 1 : -1;
        moved = true;
      } else if (y !== ty) {
        y += y < ty ? 1 : -1;
        moved = true;
      }

      if (moved) {
        put(
          x,
          y,
          z,
          steps % 4 === 0 ? wood.stripped : wood.log
        );
      }
    }

    if (gy < ty) {
      for (let yy = gy; yy < ty; yy++) {
        put(tx, yy, tz, ground.revetment);
      }
    }

    const bladeZ = tz + side;

    if (inXZ(tx, bladeZ)) {
      put(tx, ty, bladeZ, wood.planks);
      const bladeGround = terrainY(tx, bladeZ);

      if (bladeGround < ty) {
        for (let yy = bladeGround; yy < ty; yy++) {
          put(tx, yy, bladeZ, ground.revetment);
        }
      }
    }
  }

  addOar(west, 5, -1, 3, -1);
  addOar(west, 11, 1, 5, 1);
  addOar(west, 17, -1, 3, 1);

  addOar(east, 5, 1, 3, 1);
  addOar(east, 11, -1, 5, -1);
  addOar(east, 17, 1, 3, -1);

  function scorchPatch(ship, t, side) {
    const x = shipX(ship, t);
    const z = ship.cz + side * radius(t);
    const b = baseAt(t, x, z);

    put(x, b + 1, z, stone.accent);

    const nextX = x + ship.dir;

    if (inXZ(nextX, z)) {
      put(nextX, b + 1, z, stone.accent);
    }
  }

  scorchPatch(west, 7, 1);
  scorchPatch(west, 14, -1);
  scorchPatch(east, 8, -1);
  scorchPatch(east, 15, 1);

  const traceSeen = new Set();
  const traceCells = [];

  function traceCell(x, z) {
    if (!inXZ(x, z)) {
      return;
    }

    const key = x + ":" + z;

    if (traceSeen.has(key)) {
      return;
    }

    traceSeen.add(key);

    const pattern = (x * 11 + z * 7) % 23;
    let block = ground.pavement;

    if (pattern === 0 || pattern === 1) {
      block = ground.revetment;
    } else if (pattern === 2) {
      block = stone.accent;
    } else if (pattern === 4) {
      block = ground.scree;
    }

    lowColumn(x, z, block);
    traceCells.push([x, z]);
  }

  function traceBand(x, z, width) {
    for (let dz = -width; dz <= width; dz++) {
      traceCell(x, z + dz);
    }
  }

  function traceLine(x0, z0, x1, z1, width) {
    let x = x0;
    let z = z0;

    traceBand(x, z, width);

    while (x !== x1 || z !== z1) {
      if (x !== x1) {
        x += x < x1 ? 1 : -1;
        traceBand(x, z, width);
      }

      if (z !== z1) {
        z += z < z1 ? 1 : -1;
        traceBand(x, z, width);
      }
    }
  }

  traceLine(25, 6, 30, 15, 1);
  traceLine(3, 5, 0, 4, 1);
  traceLine(3, 7, 0, 8, 1);
  traceLine(52, 14, 55, 13, 1);
  traceLine(52, 16, 55, 17, 1);

  function addBallast(ship, t, side) {
    const x = shipX(ship, t);
    const bodyZ = ship.cz + side * radius(t);
    const rubbleZ = bodyZ + side;
    const joinY = baseAt(t, x, bodyZ);

    if (!inXZ(x, rubbleZ)) {
      return;
    }

    rubbleJoin(x, rubbleZ, joinY, stone.accent);

    const secondZ = rubbleZ + side;

    if (inXZ(x, secondZ)) {
      rubbleJoin(x, secondZ, joinY, stone.primary);
    }
  }

  addBallast(west, 4, -1);
  addBallast(west, 10, 1);
  addBallast(west, 16, -1);
  addBallast(east, 4, 1);
  addBallast(east, 10, -1);
  addBallast(east, 16, 1);

  for (let i = 3; i < traceCells.length; i += 4) {
    const x = traceCells[i][0];
    const z = traceCells[i][1];
    const side = i % 2 === 0 ? 1 : -1;
    const rubbleZ = z + side;

    if (!inXZ(x, rubbleZ)) {
      continue;
    }

    rubbleJoin(x, rubbleZ, seatY, stone.accent);

    let secondX = x + (i % 3 === 0 ? 1 : -1);

    if (!inXZ(secondX, rubbleZ)) {
      secondX = x - (i % 3 === 0 ? 1 : -1);
    }

    if (inXZ(secondX, rubbleZ)) {
      rubbleJoin(secondX, rubbleZ, seatY, stone.primary);
    }
  }

  const westBowY = Math.min(
    H - 1,
    baseAt(22, shipX(west, 22), west.cz) + 3
  );

  const eastBowY = Math.min(
    H - 1,
    baseAt(22, shipX(east, 22), east.cz) + 3
  );

  return {
    name: "Beached Aegean Warships",
    seatY: seatY,
    anchors: {
      landing: [28, seatY, 9],
      westBow: [25, westBowY, 6],
      eastBow: [30, eastBowY, 15],
      westShore: [0, seatY, 5],
      eastShore: [55, seatY, 16]
    }
  };
}
